#!/usr/bin/env python3
"""Replicated Key-Value Store with Leader/Follower architecture."""

import asyncio
import json
import os
import sys

import recovery

DATA_DIR = "/app/data"


def _fsync_dir(path):
    """Persist a directory entry after creating/replacing a file."""
    flags = os.O_RDONLY
    if hasattr(os, "O_DIRECTORY"):
        flags |= os.O_DIRECTORY
    fd = os.open(path, flags)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


class WAL:
    """A durable, line-oriented write-ahead log."""

    def __init__(self, path):
        self.path = path
        self.entries = []
        os.makedirs(os.path.dirname(path), exist_ok=True)
        if os.path.exists(path):
            self._load_and_repair()
        else:
            # Create the file and its directory entry before it is used.
            with open(self.path, "ab") as f:
                f.flush()
                os.fsync(f.fileno())
            _fsync_dir(os.path.dirname(path))

    def _load_and_repair(self):
        with open(self.path, "rb") as f:
            raw = f.read()

        valid = []
        lines = raw.splitlines(keepends=True)
        for offset, raw_line in enumerate(lines):
            try:
                entry = json.loads(raw_line.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError):
                # A process kill can leave a torn final append.  Everything
                # before it is intact; the incomplete record is discarded.
                if offset != len(lines) - 1:
                    raise ValueError(f"corrupt WAL record in {self.path}")
                break
            if not isinstance(entry, dict) or "op" not in entry:
                if offset != len(lines) - 1:
                    raise ValueError(f"corrupt WAL record in {self.path}")
                break
            valid.append(entry)

        canonical = b"".join(
            json.dumps(entry, separators=(",", ":")).encode("utf-8") + b"\n"
            for entry in valid
        )
        if canonical != raw:
            with open(self.path, "r+b") as f:
                f.write(canonical)
                f.truncate(len(canonical))
                f.flush()
                os.fsync(f.fileno())

        self.entries = valid

    def append(self, entry):
        encoded = json.dumps(entry, separators=(",", ":")).encode("utf-8") + b"\n"
        with open(self.path, "ab") as f:
            f.write(encoded)
            f.flush()
            os.fsync(f.fileno())
        self.entries.append(entry)
        return len(self.entries) - 1

    def truncate_through(self, index):
        """Durably remove an uncommitted proposal and everything after it."""
        if index < -1:
            raise ValueError("invalid WAL index")
        self.entries = self.entries[:index + 1]
        encoded = b"".join(
            json.dumps(entry, separators=(",", ":")).encode("utf-8") + b"\n"
            for entry in self.entries
        )
        with open(self.path, "r+b") as f:
            f.write(encoded)
            f.truncate(len(encoded))
            f.flush()
            os.fsync(f.fileno())

    @property
    def last_index(self):
        return len(self.entries) - 1 if self.entries else -1


class KVState:
    """Key-value state machine with apply tracking."""

    def __init__(self, wal_path):
        self.wal = WAL(wal_path)
        self.data = {}
        self.applied_up_to = -1

    def _apply(self, entry):
        op = entry.get("op")
        if op == "SET":
            self.data[entry["key"]] = entry.get("value")
        elif op == "DEL":
            self.data.pop(entry["key"], None)
        else:
            raise ValueError(f"unknown WAL operation: {op!r}")

    def apply_through(self, index):
        if index < self.applied_up_to:
            return True
        if index >= len(self.wal.entries):
            return False
        while self.applied_up_to < index:
            self.applied_up_to += 1
            self._apply(self.wal.entries[self.applied_up_to])
        return True

    def get(self, key):
        return self.data.get(key)

    def propose(self, op, key, value=None):
        entry = {"op": op, "key": key}
        if value is not None:
            entry["value"] = value
        return self.wal.append(entry)


def _read_index(path):
    try:
        with open(path) as f:
            return int(f.read().strip())
    except (OSError, ValueError):
        return -1


def _save_mark(path, idx):
    tmp_path = path + ".tmp"
    with open(tmp_path, "w") as f:
        f.write(str(idx))
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp_path, path)
    _fsync_dir(os.path.dirname(path))


