        mark = _read_index(self.mark_path)
        target = recovery.get_replay_target(mark, self.sync_path)
        # The two files are updated separately.  Either may be ahead after a
        # crash between their updates, and both contain only acknowledged
        # indices, so the safe recovered index is their maximum.
        self.ack_index = max(mark, target)
        # Never replay beyond a durable WAL record (also protects against a
        # truncated or corrupted mark left by an older version).
        self.ack_index = min(self.ack_index, self.state.wal.last_index)
        if self.ack_index >= 0:
            self.state.apply_through(self.ack_index)

    def _commit_local(self, idx):
        """Apply and durably record a committed index."""
        if not self.state.apply_through(idx):
            return False
        if idx > self.ack_index:
            self.ack_index = idx
            # Save the replay manifest first.  If a crash happens before the
            # mark update, recovery takes the maximum of both durable points.
            recovery.save_manifest(self.sync_path, self.ack_index)
            _save_mark(self.mark_path, self.ack_index)
        return True

