                cmd = line.decode().strip()
                if not cmd:
                    continue
                resp = await self._dispatch(cmd)
                writer.write((resp + "\n").encode())
                await writer.drain()
        except (ConnectionResetError, BrokenPipeError, asyncio.IncompleteReadError):
            pass
        finally:
            try:
                writer.close()
                await writer.wait_closed()
            except Exception:
                pass

    async def _dispatch(self, line):
        parts = line.split()
        if not parts:
            return "ERR"
        cmd = parts[0].upper()
        if cmd == "GET":
            return self._cmd_get(parts)
        elif cmd == "SET":
            return await self._cmd_set(parts)
        elif cmd == "DEL":
            return await self._cmd_del(parts)
        elif cmd == "FLUSH":
            return await self._cmd_flush()
        elif cmd == "REPLICATE":
            return await self._cmd_replicate(parts)
        elif cmd == "COMMIT":
            return await self._cmd_commit(parts)
        elif cmd == "PROMOTE":
            return await self._cmd_promote()
        elif cmd == "STATUS":
            return self._cmd_status()
        else:
            return f"ERR unknown: {cmd}"

    def _cmd_get(self, parts):
        if len(parts) != 2:
            return "ERR usage: GET <key>"
        val = self.state.get(parts[1])
        return f"OK {val}" if val is not None else "NIL"

    async def _propose_and_replicate(self, op, key, value=None):
        previous_ack = self.ack_index
        idx = self.state.propose(op, key, value)
        if self.peer_port:
            if not await self._send_replicate(idx, op, key, value):
                # The follower refused/refused to receive this proposal, so do
                # not leave a gap in its future log sequence.
                self.state.wal.truncate_through(previous_ack)
                return None
            if not await self._send_commit(idx):
                # The follower may already have the durable record; retain it
                # to preserve matching log positions on a retry.
                return None
        if not self._commit_local(idx):
            return None
        return idx

    async def _cmd_set(self, parts):
        if self.role != "leader":
            return "ERR_NOT_LEADER"
        if len(parts) < 3:
            return "ERR usage: SET <key> <value>"
        key = parts[1]
        value = " ".join(parts[2:])
        async with self.write_lock:
            idx = await self._propose_and_replicate("SET", key, value)
            return f"ERR_REPLICATE" if idx is None else f"OK {idx}"

    async def _cmd_del(self, parts):
        if self.role != "leader":
            return "ERR_NOT_LEADER"
        if len(parts) != 2:
            return "ERR usage: DEL <key>"
        async with self.write_lock:
            idx = await self._propose_and_replicate("DEL", parts[1])
            return "ERR_REPLICATE" if idx is None else f"OK {idx}"

    async def _cmd_flush(self):
        if self.role != "leader":
            return "ERR_NOT_LEADER"
        async with self.write_lock:
            target = self.ack_index
            if self.peer_port and target >= 0:
                if not await self._send_commit(target):
                    return "ERR_COMMIT"
            # Every acknowledged write is already committed locally.  FLUSH
            # rewrites both durable indices, providing an explicit sync point.
            self.ack_index = target
            recovery.save_manifest(self.sync_path, self.ack_index)
            _save_mark(self.mark_path, self.ack_index)
            return f"OK {self.ack_index}"

    async def _cmd_replicate(self, parts):
        if len(parts) < 4:
            return "ERR usage: REPLICATE <idx> <op> <key> [value]"
        try:
            idx = int(parts[1])
        except ValueError:
            return "ERR invalid index"
        op = parts[2].upper()
        key = parts[3]
        value = " ".join(parts[4:]) if len(parts) > 4 else None

