        reader = writer = None
        try:
            reader, writer = await asyncio.open_connection(self.peer_host, self.peer_port)
            writer.write((f"COMMIT {idx}\n").encode())
            await writer.drain()
            resp = await asyncio.wait_for(reader.readline(), timeout=5.0)
            return resp.decode().strip() == f"ACK {idx}"
        except Exception:
            return False
        finally:
            if writer is not None:
                writer.close()
                try:
                    await writer.wait_closed()
                except Exception:
                    pass

