    tmp_path = path + ".tmp"
    with open(tmp_path, "w") as f:
        f.write(str(idx))
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp_path, path)
    _fsync_dir(os.path.dirname(path))


def get_replay_target(ack_index, manifest_path):
    """Return the safe replay point from durable commit metadata."""
    return max(ack_index, load_manifest(manifest_path))


def on_promote(state, ack_index):
    """Apply the durable acknowledged log through the promotion point."""
    if ack_index >= 0:
        state.apply_through(ack_index)
    return ack_index
